use std::fs;
use std::path::Path;

use super::msg::ui;
use serde_json::json;

/// En-tête des fichiers générés.
pub const GENERATED_HEADER: &str =
    "Generated by TFUI - Transport Fever 3 UI Editor";

/// Anciens en-têtes, toujours reconnus (fichiers écrits avant le renommage).
const LEGACY_GENERATED_HEADERS: &[&str] = &["Generated by TF3 UI Designer"];

/// Fichier écrit par l’éditeur (en-tête actuel ou ancien) ?
pub fn has_generated_header(text: &str) -> bool {
    text.contains(GENERATED_HEADER) || LEGACY_GENERATED_HEADERS.iter().any(|h| text.contains(h))
}

#[tauri::command]
pub fn read_text_file(path: String) -> Result<String, String> {
    fs::read_to_string(&path).map_err(|e| ui("io.read", json!({ "path": path, "error": e.to_string() })))
}

/// Image locale (fond de l’aperçu) renvoyée en octets bruts, sans JSON.
#[tauri::command]
pub fn read_image_file(path: String) -> Result<tauri::ipc::Response, String> {
    let ext = Path::new(&path)
        .extension()
        .and_then(|e| e.to_str())
        .map(|e| e.to_ascii_lowercase())
        .unwrap_or_default();
    if !matches!(ext.as_str(), "png" | "jpg" | "jpeg" | "webp" | "bmp") {
        return Err(ui("io.imageFormat", json!({ "path": path })));
    }
    let bytes = fs::read(&path).map_err(|e| ui("io.read", json!({ "path": path, "error": e.to_string() })))?;
    Ok(tauri::ipc::Response::new(bytes))
}

/// Écrit un fichier binaire (export PNG de l’aperçu) : octets bruts dans le
/// corps de la requête, chemin dans l’en-tête `x-path` (encodé URI).
#[tauri::command]
pub fn write_binary_file(request: tauri::ipc::Request<'_>) -> Result<(), String> {
    let raw_path = request
        .headers()
        .get("x-path")
        .and_then(|v| v.to_str().ok())
        .ok_or_else(|| ui("io.missingPathHeader", json!({})))?;
    let path = percent_decode(raw_path);
    let tauri::ipc::InvokeBody::Raw(bytes) = request.body() else {
        return Err(ui("io.binaryBodyExpected", json!({})));
    };
    if let Some(parent) = Path::new(&path).parent() {
        if !parent.as_os_str().is_empty() {
            fs::create_dir_all(parent).map_err(|e| ui("io.mkdir", json!({ "path": path, "error": e.to_string() })))?;
        }
    }
    fs::write(&path, bytes).map_err(|e| ui("io.write", json!({ "path": path, "error": e.to_string() })))
}

/// Décodage `%XX` (UTF-8) d’un chemin passé en en-tête.
pub(crate) fn percent_decode(s: &str) -> String {
    let b = s.as_bytes();
    let mut out = Vec::with_capacity(b.len());
    let mut i = 0;
    while i < b.len() {
        // `encodeURIComponent` ne produit que de l’ASCII : découpe sûre.
        if b[i] == b'%' && i + 2 < b.len() {
            if let Ok(v) = u8::from_str_radix(&s[i + 1..i + 3], 16) {
                out.push(v);
                i += 3;
                continue;
            }
        }
        out.push(b[i]);
        i += 1;
    }
    String::from_utf8_lossy(&out).into_owned()
}

#[tauri::command]
pub fn write_text_file(path: String, content: String) -> Result<(), String> {
    if let Some(parent) = Path::new(&path).parent() {
        if !parent.as_os_str().is_empty() {
            fs::create_dir_all(parent)
                .map_err(|e| ui("io.mkdirParents", json!({ "path": path, "error": e.to_string() })))?;
        }
    }
    fs::write(&path, content).map_err(|e| ui("io.write", json!({ "path": path, "error": e.to_string() })))
}

/// Write a generated GUI file with backup + manual-file guard.
/// Error codes (prefix): `manual_file:` when existing file lacks the designer header.
#[tauri::command]
pub fn write_generated_file(
    path: String,
    content: String,
    force: bool,
) -> Result<(), String> {
    write_generated_file_inner(&path, &content, force)
}

/// Ligne d’empreinte des fichiers générés : détecte toute retouche à la main.
const FINGERPRINT_PREFIX: &str = "-- tfui:sha256=";

/// Contenu sans la ligne d’empreinte, fins de ligne normalisées (un éditeur
/// qui passe en CRLF ne compte pas comme une retouche).
fn body_for_fingerprint(text: &str) -> String {
    text.replace("\r\n", "\n")
        .lines()
        .filter(|l| !l.starts_with(FINGERPRINT_PREFIX))
        .collect::<Vec<_>>()
        .join("\n")
}

fn fingerprint(text: &str) -> String {
    use sha2::{Digest, Sha256};
    format!("{:x}", Sha256::digest(body_for_fingerprint(text).as_bytes()))
}

/// Ajoute l’empreinte sous la première ligne (en-tête).
fn stamp(content: &str) -> String {
    let line = format!("{FINGERPRINT_PREFIX}{}", fingerprint(content));
    match content.split_once('\n') {
        Some((head, rest)) => format!("{head}\n{line}\n{rest}"),
        None => format!("{content}\n{line}\n"),
    }
}

/// Fichier généré retouché à la main depuis sa dernière écriture ?
/// (Fichiers anciens sans empreinte : non détectable, considéré intact.)
pub fn hand_modified(existing: &str) -> bool {
    let recorded = existing
        .replace("\r\n", "\n")
        .lines()
        .find_map(|l| l.strip_prefix(FINGERPRINT_PREFIX).map(|h| h.trim().to_string()));
    match recorded {
        Some(h) => h != fingerprint(existing),
        None => false,
    }
}

/// Lecture seule posée sur les fichiers générés (retirée le temps d’écrire).
fn set_readonly(p: &Path, readonly: bool) {
    if let Ok(meta) = fs::metadata(p) {
        let mut perms = meta.permissions();
        #[allow(clippy::permissions_set_readonly_false)]
        perms.set_readonly(readonly);
        let _ = fs::set_permissions(p, perms);
    }
}

pub fn write_generated_file_inner(
    path: &str,
    content: &str,
    force: bool,
) -> Result<(), String> {
    let p = Path::new(path);
    if let Some(parent) = p.parent() {
        if !parent.as_os_str().is_empty() {
            fs::create_dir_all(parent)
                .map_err(|e| ui("io.mkdirParents", json!({ "path": path, "error": e.to_string() })))?;
        }
    }

    if p.is_file() {
        let existing = fs::read_to_string(p)
            .map_err(|e| ui("io.read", json!({ "path": path, "error": e.to_string() })))?;
        if !has_generated_header(&existing) && !force {
            return Err(format!(
                "manual_file:{path}"
            ));
        }
        if hand_modified(&existing) && !force {
            return Err(format!(
                "modified_by_hand:{path}"
            ));
        }
        set_readonly(p, false);
    }

    // Pas de copie de sauvegarde : le projet est versionné par l’utilisateur.
    fs::write(p, stamp(content)).map_err(|e| ui("io.write", json!({ "path": path, "error": e.to_string() })))?;
    set_readonly(p, true);
    Ok(())
}

/// Remove a previously generated GUI file (header guard). Missing file = ok.
#[tauri::command]
pub fn remove_generated_file(path: String, force: Option<bool>) -> Result<(), String> {
    remove_generated_file_inner(&path, force.unwrap_or(false))
}

pub fn remove_generated_file_inner(path: &str, force: bool) -> Result<(), String> {
    let p = Path::new(path);
    if !p.is_file() {
        return Ok(());
    }
    let existing = fs::read_to_string(p)
        .map_err(|e| ui("io.read", json!({ "path": path, "error": e.to_string() })))?;
    if !has_generated_header(&existing) {
        return Err(format!(
            "manual_file:{path}"
        ));
    }
    if hand_modified(&existing) && !force {
        return Err(format!(
            "modified_by_hand:{path}"
        ));
    }
    set_readonly(p, false);
    fs::remove_file(p).map_err(|e| ui("io.remove", json!({ "path": path, "error": e.to_string() })))
}

#[tauri::command]
pub fn list_dir_files(path: String) -> Result<Vec<String>, String> {
    let p = Path::new(&path);
    if !p.is_dir() {
        return Ok(vec![]);
    }
    let mut names = Vec::new();
    for entry in fs::read_dir(p).map_err(|e| ui("io.readDir", json!({ "path": path, "error": e.to_string() })))? {
        let entry = entry.map_err(|e| e.to_string())?;
        if entry.file_type().map(|t| t.is_file()).unwrap_or(false) {
            if let Some(name) = entry.file_name().to_str() {
                names.push(name.to_string());
            }
        }
    }
    names.sort();
    Ok(names)
}

/// Crée un fichier de l’utilisateur (ex. `<fileBase>.handlers.lua`) s’il
/// n’existe pas. Ne l’écrase jamais : `false` si le fichier existait déjà.
#[tauri::command]
pub fn create_user_file_if_absent(path: String, content: String) -> Result<bool, String> {
    create_user_file_if_absent_inner(&path, &content)
}

pub fn create_user_file_if_absent_inner(path: &str, content: &str) -> Result<bool, String> {
    use std::io::Write;
    let p = Path::new(path);
    if let Some(parent) = p.parent() {
        if !parent.as_os_str().is_empty() {
            fs::create_dir_all(parent)
                .map_err(|e| ui("io.mkdirParents", json!({ "path": path, "error": e.to_string() })))?;
        }
    }
    // `create_new` : création atomique, échoue si le fichier existe.
    match fs::OpenOptions::new().write(true).create_new(true).open(p) {
        Ok(mut f) => {
            f.write_all(content.as_bytes())
                .map_err(|e| ui("io.write", json!({ "path": path, "error": e.to_string() })))?;
            Ok(true)
        }
        Err(e) if e.kind() == std::io::ErrorKind::AlreadyExists => Ok(false),
        Err(e) => Err(ui("io.create", json!({ "path": path, "error": e.to_string() }))),
    }
}

/// Le dossier (ou un parent) est-il versionné avec git ? (`.git` dossier ou
/// fichier, ce dernier pour les worktrees et sous-modules.)
#[tauri::command]
pub fn is_versioned(path: String) -> bool {
    let mut dir = Some(Path::new(&path));
    while let Some(d) = dir {
        if d.join(".git").exists() {
            return true;
        }
        dir = d.parent();
    }
    false
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn current_and_legacy_headers_are_recognized() {
        assert!(has_generated_header("-- Generated by TFUI - Transport Fever 3 UI Editor — x"));
        assert!(has_generated_header("-- Generated by TF3 UI Designer — x"));
        assert!(!has_generated_header("-- mon code"));
    }

    #[test]
    fn user_file_is_created_once_and_never_overwritten() {
        let dir = tmp_dir("userfile");
        let path = dir.join("gui/a.handlers.lua");
        let path_s = path.to_string_lossy().to_string();
        assert!(create_user_file_if_absent_inner(&path_s, "stub").unwrap());
        fs::write(&path, "mon code").unwrap();
        assert!(!create_user_file_if_absent_inner(&path_s, "stub").unwrap());
        assert_eq!(fs::read_to_string(&path).unwrap(), "mon code");
        let _ = fs::remove_dir_all(&dir);
    }

    #[test]
    fn versioned_when_a_parent_has_git() {
        let dir = tmp_dir("git");
        let sub = dir.join("a/b");
        fs::create_dir_all(&sub).unwrap();
        // Le dossier temporaire système n’est pas versionné.
        assert!(!is_versioned(sub.to_string_lossy().to_string()));
        fs::create_dir_all(dir.join(".git")).unwrap();
        assert!(is_versioned(sub.to_string_lossy().to_string()));
        let _ = fs::remove_dir_all(&dir);
    }
    use std::fs;

    fn tmp_dir(name: &str) -> std::path::PathBuf {
        let p = std::env::temp_dir().join(format!("tfui_fs_{name}_{}", std::process::id()));
        let _ = fs::remove_dir_all(&p);
        fs::create_dir_all(&p).unwrap();
        p
    }

    #[test]
    fn write_new_file_ok_with_fingerprint_and_readonly() {
        let dir = tmp_dir("new");
        let path = dir.join("a.script.lua");
        let path_s = path.to_string_lossy().to_string();
        write_generated_file_inner(&path_s, "-- Generated by TF3 UI Designer\nx", false).unwrap();
        let written = fs::read_to_string(&path).unwrap();
        assert!(written.starts_with("-- Generated by TF3 UI Designer\n-- tfui:sha256="));
        assert!(written.ends_with("\nx"));
        assert!(!hand_modified(&written));
        assert!(fs::metadata(&path).unwrap().permissions().readonly());
        // Réécriture par l’éditeur malgré la lecture seule.
        write_generated_file_inner(&path_s, "-- Generated by TF3 UI Designer\ny", false).unwrap();
        assert!(fs::read_to_string(&path).unwrap().ends_with("\ny"));
        set_readonly(&path, false);
        let _ = fs::remove_dir_all(&dir);
    }

    #[test]
    fn refuse_manual_without_force() {
        let dir = tmp_dir("manual");
        let path = dir.join("hand.lua");
        fs::write(&path, "-- hand written\n").unwrap();
        let path_s = path.to_string_lossy().to_string();
        let err = write_generated_file_inner(&path_s, "new", false).unwrap_err();
        assert!(err.starts_with("manual_file:"));
        let _ = fs::remove_dir_all(&dir);
    }

    #[test]
    fn refuse_hand_modified_generated_without_force_and_no_bak() {
        let dir = tmp_dir("hand_mod");
        let path = dir.join("g.lua");
        let path_s = path.to_string_lossy().to_string();
        write_generated_file_inner(&path_s, "-- Generated by TF3 UI Designer\nold\n", false).unwrap();
        set_readonly(&path, false);
        let edited = fs::read_to_string(&path).unwrap().replace("old", "retouche");
        fs::write(&path, edited).unwrap();
        let err = write_generated_file_inner(&path_s, "-- Generated by TF3 UI Designer\nnew\n", false).unwrap_err();
        assert!(err.starts_with("modified_by_hand:"));
        assert!(fs::read_to_string(&path).unwrap().contains("retouche"));
        // Fins de ligne seulement changées : pas une retouche.
        write_generated_file_inner(&path_s, "-- Generated by TF3 UI Designer\nnew\n", true).unwrap();
        set_readonly(&path, false);
        let crlf = fs::read_to_string(&path).unwrap().replace('\n', "\r\n");
        assert!(!hand_modified(&crlf));
        assert!(!Path::new(&format!("{path_s}.bak")).exists());
        let _ = fs::remove_dir_all(&dir);
    }

    #[test]
    fn remove_generated_ok_and_refuse_manual() {
        let dir = tmp_dir("rm");
        let gen = dir.join("g.lua");
        fs::write(&gen, "-- Generated by TF3 UI Designer\nx\n").unwrap();
        remove_generated_file_inner(&gen.to_string_lossy(), false).unwrap();
        assert!(!gen.is_file());
        let hand = dir.join("h.lua");
        fs::write(&hand, "-- hand\n").unwrap();
        let err = remove_generated_file_inner(&hand.to_string_lossy(), false).unwrap_err();
        assert!(err.starts_with("manual_file:"));
        let _ = fs::remove_dir_all(&dir);
    }
}
